 await assert.rejects(arrayTampered.fetch(`${host}/sendMessage`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:{recipient:[bob.identity,eve.identity],messageBox:'inbox',messageId:['tamper-array-b','tamper-array-e'],body:'forged'}}),requireMutualAuth:true,expectedIdentityKey:server,allowPayments:false}));assert.equal(arrayTamperedStatus,401);
 let ignoredTamperStatus;const mutateIgnored=async(url,init)=>{const headers=new Headers(init.headers);if(String(url).endsWith('/sendMessage')&&headers.has('x-bsv-auth-request-id')){const response=await fetch(url,{...init,body:String(init.body).replace(eve.identity,aliceKey)});ignoredTamperStatus=response.status;return response;}return fetch(url,init)};const ignoredTampered=new AuthFetch(wallet(2),undefined,undefined,undefined,{responseTimeoutMs:1500},mutateIgnored);
 await assert.rejects(ignoredTampered.fetch(`${host}/sendMessage`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:{recipient:eve.identity,recipients:[bob.identity],messageBox:'inbox',messageId:'tamper-ignored',body:'forged'}}),requireMutualAuth:true,expectedIdentityKey:server,allowPayments:false}));assert.equal(ignoredTamperStatus,401);
