 await assert.rejects(paidFetcher.fetch(`${host}/sendMessage`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:{recipient:bob.identity,messageBox:'inbox',messageId:'payment-field',body:'synthetic'},payment:null}),requireMutualAuth:true,expectedIdentityKey:server,allowPayments:false}));assert.equal(paymentStatus,501);
